// Boundary validation. Everything downstream may assume a well-formed ticket, so this
// is the only place that trusts the caller.
const cfg = $('Config').first().json;
const raw = $json.body ?? {};
const errors = [];

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const customerEmail = str(raw.customerEmail);
const subject = str(raw.subject);
const body = str(raw.body);

if (!customerEmail) errors.push({ field: 'customerEmail', message: 'is required' });
else if (!EMAIL.test(customerEmail)) errors.push({ field: 'customerEmail', message: 'must be a valid email address' });

if (!subject) errors.push({ field: 'subject', message: 'is required' });
else if (subject.length > cfg.maxSubjectChars) errors.push({ field: 'subject', message: `must be at most ${cfg.maxSubjectChars} characters` });

if (!body) errors.push({ field: 'body', message: 'is required' });
else if (body.length > cfg.maxBodyChars) errors.push({ field: 'body', message: `must be at most ${cfg.maxBodyChars} characters` });

const ticket = {
  ticket_id: `TKT-${$execution.id}`,
  customer_email: customerEmail,
  subject,
  body,
  question: [subject, body].filter(Boolean).join('\n\n'),
  received_at: new Date().toISOString(),
};

return [{ json: { valid: errors.length === 0, errors, ticket } }];

// The In-Memory store returns up to topK documents regardless of score whenever it holds
// anything at all. So zero documents back means the index itself is empty (fresh container,
// restart, or TTL eviction) - not that the question had no answer. That distinction is what
// drives the cold-index self-heal below.
const ticket = $('Validate Intake').first().json.ticket;

const hits = $input
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.document && typeof j.document.pageContent === 'string')
  .map((j) => ({
    article_id: j.document.metadata?.article_id ?? null,
    title: j.document.metadata?.title ?? 'Untitled',
    category: j.document.metadata?.category ?? null,
    score: Number(j.score ?? 0),
    text: j.document.pageContent,
  }))
  .sort((a, b) => b.score - a.score);

return [{
  json: {
    ...ticket,
    hits,
    top_score: hits.length ? hits[0].score : 0,
    index_cold: hits.length === 0,
    retrieval_attempt: 1,
  },
}];

