// anything at all. So zero documents back means the index itself is empty (fresh container,
// restart, or TTL eviction) - not that the question had no answer. That distinction is what
// drives the cold-index self-heal below.
const ticket = $('Validate Intake').first().json.ticket;

const hits = $input
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.document && typeof j.document.pageContent === 'string')
  .map((j) => ({
    article_id: j.document.metadata?.article_id ?? null,
    title: j.document.metadata?.title ?? 'Untitled',
    category: j.document.metadata?.category ?? null,
    score: Number(j.score ?? 0),
    text: j.document.pageContent,
  }))
  .sort((a, b) => b.score - a.score);

return [{
  json: {
    ...ticket,
    hits,
    top_score: hits.length ? hits[0].score : 0,
    index_cold: hits.length === 0,
    retrieval_attempt: 2,
  },
}];

// Single funnel for both retrieval branches, so every node downstream has one stable
// address for the RAG context regardless of whether the index needed rehydrating.
const cfg = $('Config').first().json;
const src = $input.first().json;
const minScore = Number(cfg.minRelevanceScore);

const all = Array.isArray(src.hits) ? src.hits : [];
const kept = all.filter((h) => h.score >= minScore);

const kb_context = kept.length
  ? kept
      .map((h, i) =>
        [
          `--- ARTICLE ${i + 1} ---`,
          `Title: ${h.title}`,
          `Category: ${h.category}`,
          `Relevance: ${h.score.toFixed(3)}`,
          '',
          h.text,
        ].join('\n'),
      )
      .join('\n\n')
  : 'NO ARTICLES MATCHED THIS QUESTION.';

return [{
  json: {
    ticket_id: src.ticket_id,
    customer_email: src.customer_email,
    subject: src.subject,
    body: src.body,
    question: src.question,
    received_at: src.received_at,
    retrieval_attempt: src.retrieval_attempt,
    top_score: src.top_score,
    min_relevance_score: minScore,
    considered: all.map((h) => ({ title: h.title, score: Number(h.score.toFixed(4)) })),
    matched_hits: kept.map((h) => ({
      article_id: h.article_id,
      title: h.title,
      category: h.category,
      score: Number(h.score.toFixed(4)),
    })),
    sources: kept.map((h) => h.title),
    has_match: kept.length > 0,
    kb_context,
  },
}];

