{
  "type": "object",
  "required": [
    "reply",
    "grounded",
    "cited_titles"
  ],
  "properties": {
    "reply": {
      "type": "string",
      "description": "The full customer-facing reply as plain text"
    },
    "grounded": {
      "type": "boolean",
      "description": "true only when the factual content of the reply came from the supplied articles"
    },
    "cited_titles": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Exact titles of the articles actually used. Empty array when grounded is false."
    }
  }
}

