// One canonical record. Both adapters and the API response read from here, so the sink
// and the caller can never disagree about what was decided.
const cfg = $('Config').first().json;
const ctx = $('Consolidate Context').first().json;
const cls = $('Classify Ticket').first().json.output ?? {};
const drf = $('Draft Grounded Reply').first().json.output ?? {};

const SEVERITIES = ['urgent', 'high', 'normal', 'low'];
const severity = SEVERITIES.includes(cls.severity) ? cls.severity : 'normal';

// kb_matched requires BOTH a retrieval hit above the score floor AND the drafting model
// confirming it actually grounded the reply in those articles. Either alone is not proof.
const cited = Array.isArray(drf.cited_titles) ? drf.cited_titles.filter(Boolean) : [];
const kb_matched = Boolean(drf.grounded) && ctx.has_match && cited.length > 0;

return [{
  json: {
    ticket_id: ctx.ticket_id,
    customer_email: ctx.customer_email,
    subject: ctx.subject,
    body: ctx.body,
    intent: String(cls.intent ?? 'unclassified'),
    severity,
    sentiment: String(cls.sentiment ?? 'neutral'),
    summary: String(cls.summary ?? '').slice(0, 300),
    draft_reply: String(drf.reply ?? ''),
    cited_titles: cited,
    sources: cited.length ? cited.join(' | ') : 'none',
    kb_matched,
    grounded_flag: Boolean(drf.grounded),
    has_match: ctx.has_match,
    top_score: ctx.top_score,
    considered: ctx.considered,
    retrieval_attempt: ctx.retrieval_attempt,
    is_urgent: severity === 'urgent',
    sla_minutes: Number(cfg.urgentSlaMinutes),
    received_at: ctx.received_at,
  },
}];

// The escalation adapter only runs for urgent tickets, so reading it has to be guarded -
// $('node') throws when that node did not execute on this run.
const cfg = $('Config').first().json;
const rec = $('Assemble Ticket Record').first().json;
const storeReceipt = $input.first().json;

let escalation = null;
try {
  escalation = $('Adapter: Escalation Page').first().json;
} catch (e) {
  escalation = null;
}

const preview = rec.draft_reply.length > cfg.draftPreviewChars
  ? rec.draft_reply.slice(0, cfg.draftPreviewChars).trimEnd() + '...'
  : rec.draft_reply;

return [{
  json: {
    ticketId: rec.ticket_id,
    severity: rec.severity,
    intent: rec.intent,
    sentiment: rec.sentiment,
    kbMatched: rec.kb_matched,
    sources: rec.cited_titles,
    topRelevanceScore: Number(rec.top_score.toFixed(4)),
    draftPreview: preview,
    escalated: Boolean(escalation?.paged),
    slaDueAt: escalation?.sla_due_at ?? null,
    stored: Boolean(storeReceipt?.stored),
    receivedAt: rec.received_at,
  },
}];

// Reached only via a node's error output. Turns an internal failure into an honest
// API error rather than a silent empty 200.
// A node's error output emits the original input item with `error` appended, and
// $prevNode names whichever of the four guarded nodes routed here.
const err = $json.error ?? $json;
const rec = (() => { try { return $('Assemble Ticket Record').first().json; } catch (e) { return null; } })();
const ticketId = rec?.ticket_id
  ?? (() => { try { return $('Validate Intake').first().json.ticket.ticket_id; } catch (e) { return null; } })();

return [{
  json: {
    error: 'upstream_dependency_failed',
    message: 'The ticket was accepted but could not be triaged. It has not been lost - this '
      + 'execution is recorded in core_error_log for replay.',
    ticketId,
    failedNode: String($prevNode?.name ?? 'unknown'),
    detail: String(err?.message ?? err ?? 'unknown error').slice(0, 500),
    executionId: $execution.id,
  },
}];

// The caller already has its 502. Re-throwing here keeps the execution in the failed
// state so settings.errorWorkflow ([CORE] Error Handler) still logs it - answering the
// caller politely must not hide the incident from operators.
const d = $json;
throw new Error(`Triage failed at ${d.failedNode}: ${d.detail}`);
